"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[8738],{8738:function(e){e.exports=JSON.parse('{"generated":"2026-10-26 00:10 KST","source_file":"@reports/2026-10-26-raw.json","articles_total":33,"articles_summarized":33,"articles_skipped":0,"date_range":{"from":"2026-10-25","to":"2026-10-25"},"pages":[{"title":"Expanding the Cyber Verification Program","source":"https://www.anthropic.com/news/cyber-verification-program","published_date":"Date not detected","type":"Security","what_its_about":"Anthropic이 검증된 보안 전문가에게 고급 사이버 기능과 완화된 안전 필터를 제공하는 사이버 검증 프로그램(CVP)의 확장 개편안을 발표했습니다.","key_points":["보안 업무의 성격과 범위에 따라 차등화된 3단계 접근 등급(Defense Access, Red Team Access 등) 체계로 개편되었습니다.","선정된 보안 팀은 Claude Opus 5.5, Claude Sonnet 5.5, Claude Mythos 5.1 등 최상위 모델의 사이버 보안 역량을 활용할 수 있습니다.","기존의 Project Glasswing과 CVP를 통합하여 보안 관제, 사고 대응, 리버스 엔지니어링, 인가된 침투 테스트 등을 체계적으로 지원합니다."],"notable_data_or_quotes":["지난 6개월간 Project Glasswing과 CVP 두 프로그램을 통해 신뢰 기반 접근을 제공해 옴","Defense Access 등급 신청은 수일 내 검토, Red Team Access 등급 신청은 수 주간의 검토 소요 예상"],"intended_audience":"기업\xb7기관의 보안 관제(SOC) 및 침해사고 대응(IR) 팀, 레드팀, 침투 테스트 전문가, 보안 연구원","content_notes":null},{"title":"Donating Agent Skills to the Agentic AI Foundation","source":"https://www.anthropic.com/news/donating-agent-skills-to-the-agentic-ai-foundation","published_date":"Date not detected","type":"Tools/Dev","what_its_about":"Anthropic이 AI 에이전트에 전문 지식과 워크플로우를 제공하는 개방형 표준인 Agent Skills를 리눅스 재단 산하의 Agentic AI Foundation(AAIF)에 기증했습니다.","key_points":["ChatGPT, Cursor, GitHub Copilot, VS Code 등 70개 이상의 에이전트 플랫폼에 적용된 Agent Skills 표준이 중립적 운영을 위해 AAIF로 기증되었습니다.","표준 명칭, 로고, GitHub 조직, agentskills.io 도메인이 모두 기증되며, Anthropic, Google, OpenAI 등의 엔지니어들이 개인 자격으로 유지 관리에 참여합니다.","향후 버전별 릴리스, 공식 제안 프로세스, 스킬 작성 및 설치 관련 보안 지침을 포함하는 로드맵이 추진될 예정입니다."],"notable_data_or_quotes":["More than 70 agent platforms, including ChatGPT, Cursor, GitHub Copilot, and VS Code, have integrated Agent Skills","December 2025","October 2025","1 million skills have been published and nearly 280 million installed","David Soria Parra and Mahesh Murag as Lead Maintainers"],"intended_audience":"AI 에이전트 개발자, 오픈소스 소프트웨어 엔지니어 및 AI 플랫폼 기술 리더","content_notes":null},{"title":"Open call for guest investigators in the life sciences","source":"https://www.anthropic.com/news/open-call-guest-investigators-life-sciences","published_date":"Date not detected","type":"Research","what_its_about":"Anthropic이 생명과학 분야 연구자들을 초청하여 Claude를 활용한 공동 연구 프로젝트를 진행하는 객원 연구원 프로그램을 발표했습니다.","key_points":["학계, 비영리단체, 정부 연구소의 수석 연구자 및 연구 그룹을 대상으로 인과적 인간 생물학, 구조/계산 분자생물학, 신약 개발 등에 Claude를 활용하는 연구 제안서를 모집합니다.","선발된 객원 연구원은 8~12주 동안 Anthropic 연구진과 직접 협업하며, 모델 및 하네스 구동 비용은 전액 무료로 지원되고 도출된 성과물과 코드는 오픈소스로 공개됩니다.","참여 연구자는 데이터 권리와 후속 연구 권리를 온전히 유지하며, 접수는 약 14일 동안 진행됩니다."],"notable_data_or_quotes":["8–12 weeks","at no cost to them","approximately 14 days","Life Sciences Verification Program","AI for Science initiative"],"intended_audience":"생명과학, 분자생물학, 의약화학 및 신약 개발 분야 연구원과 학계 전문가","content_notes":null},{"title":"Physicist Christopher Stubbs joins Anthropic\'s Long-Term Benefit Trust","source":"https://www.anthropic.com/news/christopher-stubbs-joins-long-term-benefit-trust","published_date":"Date not detected","type":"Business","what_its_about":"하버드대 물리학자이자 전 이과대학장인 Christopher Stubbs 박사가 AI 안전 및 공익 사명을 감독하는 Anthropic의 롱텀 베네핏 트러스트(Long-Term Benefit Trust)에 합류했다.","key_points":["우주 가속 팽창 발견 기여 및 정부 안보 자문 이력을 지닌 Christopher Stubbs 박사가 Anthropic의 공익 신탁(Trust)에 합류함","해당 신탁은 Anthropic 이사회 과반수를 임명할 권한을 가지며, AI의 위험과 사회적 영향 등 중요 의사결정을 자문하여 상업적 성장과 공익의 균형을 유지하는 역할을 수행함","Anthropic은 첫 공익 보고서(Public Benefit Report)를 발표하고, 향후 회사 성장에 맞춰 지분을 확대하는 공익 펀드(Anthropic Public Benefit Fund) 신설 계획을 공개함"],"notable_data_or_quotes":["Christopher Stubbs: \\"I am honored to join Anthropic’s Long-Term Benefit Trust and to help the company deliver on its public benefit mission... As a grandfather, I want to help ensure that AI is developed and deployed for the long-term benefit of humanity.\\"","Daniela Amodei: \\"As AI starts to transform how science itself is done, Chris’s intellectual honesty, rigor, and commitment to the truth are the values we want shaping the future of this technology...\\"","1998년 High-Z Supernova Search Team 일원으로 우주 가속 팽창 발견에 기여해 기초물리학 브레이크스루상(Breakthrough Prize in Fundamental Physics) 수상","2018~2024년 하버드대 이과대학장(Dean of Science) 역임"],"intended_audience":"AI 거버넌스 및 안전 정책 관계자, 인공지능 윤리 연구자, Anthropic 기업 동향에 관심 있는 테크 업계 종사자","content_notes":null},{"title":"An update on independent evaluators","source":"https://www.anthropic.com/news/an-update-on-independent-evaluators","published_date":"Date not detected","type":"Security","what_its_about":"Anthropic이 프론티어 AI 모델의 안전성 검증을 위해 비영리 평가 기관 METR 연구진에게 내부 직원 수준의 접근 권한을 부여하며 외부 독립 평가를 본격화한다는 내용입니다.","key_points":["비영리 평가 단체 METR 직원 6명에게 사내 하드웨어, 사무 공간 및 내부 도구 접근 권한을 부여해 직원 수준의 심층 평가를 진행하도록 지원했습니다.","상업적 기밀이나 악용 위험 때문에 대중에 공개하기 어려운 안전 정보를 독립 평가자에게 공유하고 위험 평가 결과를 공개하도록 했습니다.","SecureBio, Accenture와도 평가 협력을 진행 중이며 Hugging Face를 비롯한 여러 조직과 초기 논의를 진행하고 있습니다."],"notable_data_or_quotes":["White House Accord on Super Intelligence","We’ve onboarded six METR employees with company hardware, office space, and access to internal tools and systems that are roughly on par with what our own risk assessment teams have access to.","METR will publish the results of its risk assessments. Anthropic can’t veto publication"],"intended_audience":"AI 안전 연구자, 정책 입안자, 거버넌스 및 컴플라이언스 전문가, 프론티어 AI 개발자","content_notes":null},{"title":"Introducing Mistral Large 4","source":"https://mistral.ai/news/mistral-large-4/","published_date":"Date not detected","type":"Tools/Dev","what_its_about":"Mistral AI가 1조 개의 파라미터와 520억 개의 활성 파라미터를 갖춘 네이티브 멀티모달 오픈 가중치 모델 Mistral Large 4의 공개 프리뷰를 발표했습니다.","key_points":["총 1조 파라미터(활성 파라미터 520억 개) 규모의 네이티브 멀티모달 오픈 가중치 모델로, 코딩\xb7에이전틱 워크플로\xb7멀티모달 이해 전반에서 최고 수준의 성능을 제공합니다.","유럽 소재 데이터센터에서 3,800개의 NVIDIA Grace Blackwell GPU를 사용해 처음부터 학습되었으며, 이달 말 오픈 가중치가 정식 공개될 예정입니다.","사이버보안, 금융, 법률 등 주요 엔터프라이즈 워크로드에서 오픈 모델 중 SOTA 성능을 기록하며 자체 배포를 통한 보안 자율성을 지원합니다."],"notable_data_or_quotes":["1 trillion-parameter natively multimodal model with 52 billion active parameters","3,800 NVIDIA Grace Blackwell GPUs in Mistral’s own datacenters in Europe","Weights drop end of this month","spanning more than 160 languages, including every official language of the European Union"],"intended_audience":"AI 연구자, 오픈소스 LLM 활용 개발자, 엔터프라이즈 보안 및 엔지니어링 전문가","content_notes":null},{"title":"Mistral Advances AI for Engineering with NVIDIA","source":"https://mistral.ai/news/mistral-nvidia-ai-for-industrial-engineering/","published_date":"Date not detected","type":"Tools/Dev","what_its_about":"미스트랄(Mistral)과 엔비디아(NVIDIA)가 협력하여 고성능 AI 모델과 가속 컴퓨팅 기술을 결합해 시뮬레이션 및 엔지니어링 워크플로우를 혁신하고 공공 벤치마크를 구축합니다.","key_points":["Mistral Large 4 모델과 엔비디아의 CUDA-X, NVIDIA Warp, Omniverse 기술을 결합하여 시뮬레이션 가속화 및 3D 에셋 생성 워크플로우 개발","컴퓨터 지원 엔지니어링(CAE) 및 전자 설계 자동화(EDA) 분야의 물리 AI와 에이전틱 AI 평가를 위한 공개 벤치마크 및 데이터셋 구축","항공우주, 자동차, 반도체 등 제조\xb7공학 산업 전반의 차세대 제품 설계 및 시뮬레이션 주기 대폭 단축"],"notable_data_or_quotes":["\\"For too long, the pace of engineering has been set by the pace of simulation. With Mistral\'s open-weight models and physics AI capabilities, combined with NVIDIA’s accelerated computing stack, we’re giving engineers faster simulation cycles, as well as open benchmarks rigorous enough to validate agents on real CAE and EDA work.\\" - Neil Ashton, VP of Computational Engineering, Mistral","“The next wave of engineering breakthroughs will come from exploring ideas that were once too complex or time-consuming to test” - Tim Costa, VP and GM of Industrial and Computational Engineering, NVIDIA","Mistral Large 4","NVIDIA CUDA-X","NVIDIA Warp","NVIDIA Omniverse"],"intended_audience":"엔지니어링 시뮬레이션 연구자, CAE/EDA 엔지니어, 산업용 AI 및 HPC 개발자","content_notes":null},{"title":"Voxtral 3","source":"https://mistral.ai/news/voxtral-3/","published_date":"Date not detected","type":"Tools/Dev","what_its_about":"Mistral AI가 실시간 다단계 음성 대화와 워크플로우 자동화를 지원하는 음성 모델 제품군 및 SDK인 Voxtral 3을 출시했습니다.","key_points":["Voxtral 3은 음성 인식(STT), 추론, 도구 호출, 음성 합성(TTS)을 실시간 단일 스트리밍 파이프라인으로 통합한 음성 에이전트 SDK 및 모델 제품군입니다.","50개 이상의 다국어 음성 인식, 화자 분리, 턴 종료 감지 및 감정 적응형 음성 합성 기능을 지원합니다.","Mistral의 EU 호스팅 API 또는 자체 인프라 배포를 지원하여 데이터 주권과 보안 통제권을 제공합니다."],"notable_data_or_quotes":["50+ languages","Voxtral Small Transcribe 3"],"intended_audience":"음성 에이전트, 고객센터 챗봇, 가상 비서를 개발하는 AI 엔지니어 및 기업 솔루션 개발자","content_notes":null},{"title":"Introducing Timestral","source":"https://mistral.ai/news/timestral/","published_date":"Date not detected","type":"Tools/Dev","what_its_about":"Mistral이 최대 209M 파라미터 크기로 주요 벤치마크 1위를 달성한 다변량 시계열 파운데이션 모델 패밀리 \'Timestral\'을 공개했습니다.","key_points":["Mistral의 첫 시계열 파운데이션 모델인 Timestral은 5M, 28M, 123M, 209M 파라미터의 4가지 크기로 제공되며 CPU에서도 효율적으로 실행됩니다.","합성 사전학습, 공변량 인식 어텐션, 긴 문맥 학습을 결합하여 과거 및 미래 공변량을 지원하는 확률론적 다변량 제로샷 예측을 지원합니다.","가장 큰 209M 모델은 이전 최고 성능 모델 파라미터의 3분의 2 수준임에도 GIFT-Eval, TIME, fev-bench 3대 주요 공개 벤치마크에서 모두 1위를 기록했습니다."],"notable_data_or_quotes":["5M, 28M, 123M, 209M parameters","GIFT-Eval, TIME, fev-bench","ranks first on all three of the field\'s main public benchmarks, GIFT-Eval, TIME, and fev-bench, outperforming the previous state of the art with only two-thirds of the model parameters"],"intended_audience":"시계열 데이터 예측 및 파운데이션 모델을 활용하려는 머신러닝 엔지니어, 데이터 사이언티스트, 산업\xb7금융 엔터프라이즈 개발자","content_notes":null},{"title":"Hallo, Deutschland!","source":"https://mistral.ai/news/hallo-deutschland/","published_date":"Date not detected","type":"Business","what_its_about":"프랑스 AI 기업 Mistral이 독일 뮌헨에 새로운 거점을 열고 유럽 최대 산업 경제국에서 피직스 AI(Physics AI) 및 산업용 AI 역량을 강화한다.","key_points":["Mistral이 독일 뮌헨에 새 허브를 개설하고 피직스 AI와 산업용 AI 연구팀 및 엔터프라이즈 엔지니어를 배치함","유럽의 AI 주권을 보장하기 위해 2030년까지 1GW 규모의 유럽 컴퓨팅 인프라를 구축할 계획 발표","BMW(충돌 시뮬레이션 및 엔지니어링 AI)와 Siemens Energy 등 독일 주요 기업과 협력하여 대규모 물리 시뮬레이션 AI 모델링 가속화 추진"],"notable_data_or_quotes":["Mistral will build one gigawatt of European compute capacity by 2030.","Following our acquisition of Emmi AI in May 2026, more than 30 physicists, researchers, and engineers with unique expertise in Physics and Engineering AI joined Mistral.","Dr. Karsten Wildberger, German Federal Minister for Digital Transformation and Government Modernisation: \'Mistral is a powerful example of what Europe can achieve: developing cutting-edge technology, turning it into a global success, and taking responsibility at the same time.\'"],"intended_audience":"유럽 제조\xb7산업 분야 엔터프라이즈 관계자, 산업용 AI 연구자, 테크 정책 및 비즈니스 리더","content_notes":null},{"title":"The hottest AI wearables and gadgets you should know about","source":"https://techcrunch.com/2026/10/25/the-hottest-ai-wearables-and-gadgets-you-should-know-about/","published_date":"2026-10-25","type":"Consumer","what_its_about":"일상의 생산성 향상과 정서적 교감을 지원하는 주요 AI 웨어러블 및 휴대용 기기들의 동향과 특징을 소개합니다.","key_points":["목걸이, 반지, 밴드 형태의 다양한 AI 기기가 일상 대화 녹음 및 정리, 감정 지원 동반자 역할을 목표로 출시되고 있습니다.","아마존이 인수한 Bee는 $49.99의 기본 펜던트와 함께 신규 기기 Bee Frontier($74.99), Bee Eclipse($99.99)를 출시하며 알렉사 연동 및 저렴한 가격대를 내세웠습니다.","정서적 교감을 제공하는 Friend($129)는 감시 자본주의 논란 속에서 자체 스피커를 탑재한 Friend 2.0을 공개했고, Limitless($99)는 회의 및 대화 요약 기능에 집중하고 있습니다."],"notable_data_or_quotes":["Bee: $49.99 (월 구독료 $19)","Amazon: 2025년 7월 웨어러블 스타트업 Bee 인수 후 Bee Frontier($74.99) 및 Bee Eclipse($99.99) 출시","Friend: $129 (뉴욕 지하철 광고에 \'surveillance capitalism\' 등 반발 문구 낙서)","Limitless: $99 (월 10시간 무료 AI 기능 제공, 무제한 옵션 월 $29)"],"intended_audience":"최신 AI 기술 및 웨어러블 기기, 스마트 라이프스타일 테크에 관심이 있는 일반 소비자 및 IT 종사자","content_notes":"본문 마지막 부분(Meta 관련 내용)이 끊겨 있어 내용이 다소 불완전함"},{"title":"Researchers from Stanford and UC Berkeley Introduce TokenGate: Token-Gated Attention Makes Long-Context Prefill Up to 11.3x Faster","source":"https://www.marktechpost.com/2026/10/25/stanford-berkeley-tokengate-learned-token-pruning-llm-prefill/","published_date":"2026-10-25","type":"Research","what_its_about":"스탠포드와 UC 버클리 연구진이 긴 컨텍스트 사전 채우기(prefill) 처리 속도를 최대 11.3배 높이고 메모리 사용량을 크게 줄이는 학습 기반 토큰 가지치기 모듈 TokenGate를 공개했다.","key_points":["TokenGate는 기존 사전학습 LLM에 결합할 수 있는 드롭인 모듈로, 중요 토큰만 선별 처리하여 정확도 저하 없이 첫 토큰 생성 시간(TTFT)을 1.4배에서 11.3배까지 단축한다.","상위 K개 토큰을 선택하는 비미분 연산의 한계를 MoE 라우터 방식을 차용해 어텐션 로짓 편향으로 역전파가 가능하도록 설계했다.","질문 부분은 보존하면서 문서 토큰만 가지치기하며, 최대 프리필 메모리를 1.5배에서 3.4배까지 절감하고 Qwen3.5-2B와 같은 하이브리드 어텐션 모델에도 적용 가능하다."],"notable_data_or_quotes":["1.4x to 11.3x faster time-to-first-token (TTFT)","Peak prefill memory drops 1.5x to 3.4x","NIAH 16k at 11.3x faster TTFT and 3.42x lower memory","TTFT gain hits 13.0x at 128k","Apache-2.0"],"intended_audience":"LLM 인프라 및 서빙 최적화 엔지니어, 긴 컨텍스트 모델 연구자 및 개발자","content_notes":null},{"title":"Anthropic Launches OSS Scanner, a Free AI Vulnerability Scanner","source":"https://www.marktechpost.com/2026/10/25/anthropic-launches-oss-scanner-a-free-ai-vulnerability-scanner/","published_date":"2026-10-25","type":"Security","what_its_about":"Anthropic이 Claude Mythos 등 자사의 최신 모델을 활용해 주요 오픈소스 프로젝트의 취약점을 무료로 탐지해 주는 opt-in 프로그램 \'OSS Scanner\'를 출시했다.","key_points":["핵심 오픈소스 프로젝트 메인테이너가 등록하면 격리된 가상머신 환경에서 최신 AI 모델이 코드베이스의 보안 취약점을 점검하고 재현 코드 및 패치를 제안한다.","사람의 수동 검토 없이 보고서가 메인테이너에게 직접 전달되어 신속한 발견이 가능하지만 분류 작업 부담이 프로젝트 팀에 전가될 수 있다.","자체 감사 결과 치명적/높음 등급 취약점의 88%가 유효했으며, wolfSSL의 경우 74개 보고서 중 72개가 유효해 5건의 CVE가 등록되는 등 높은 정확도를 보였다."],"notable_data_or_quotes":["출시 11일 만에 치명적(Critical) 77건, 높음(High) 803건의 모델 평가 취약점 발견","10월 19일 기준 약 650개 신청 중 114개 프로젝트 수락","감사된 97건 중 85건(88%)이 공개 기준 충족, 오탐(false positive)은 단 1건","curl은 영향받던 High 등급 취약점 CVE-2026-92392를 패치하여 10월 14일 8.23.0 버전 배포","CyberGym 벤치마크에서 LLM의 취약점 발견율이 20% 미만에서 85% 이상으로 상승"],"intended_audience":"오픈소스 소프트웨어 메인테이너, 보안 연구원, 개발자 및 보안 담당자","content_notes":null},{"title":"Microsoft Open-Sources Agensh: A Multi-Agent Harness for 1,024 Agents","source":"https://www.marktechpost.com/2026/10/24/microsoft-agensh-multi-agent-harness-1024-agents/","published_date":"2026-10-25","type":"Tools/Dev","what_its_about":"마이크로소프트 리서치가 중앙 오케스트레이터 없이 최대 1,024개의 코딩 에이전트가 자율적으로 협업할 수 있는 탈중앙화 멀티 에이전트 하네스 \'Agensh\'를 오픈소스로 공개했다.","key_points":["중앙 오케스트레이터의 병목 한계를 극복하기 위해 작업자 에이전트들이 스스로 서브태스크를 선택하고 협업하는 5단계 루프 방식을 도입했다.","에이전트 간 협업을 위해 공유 코드 저장소(Gitea), 다이렉트 메시징(Mattermost), 공유 컨텍스트 보드(DeLM 기반) 등 3가지 서비스를 활용한다.","ProgramBench의 고난도 5개 과제에서 1개부터 최대 1,024개 에이전트까지 확장 실험을 진행해 성능 향상과 소요 시간 단축을 검증했다."],"notable_data_or_quotes":["테스트 에이전트 규모: 1개 ~ 1,024개","각 작업자당 입력 토큰 한도: 272,000 토큰, 출력 토큰 한도: 128,000 토큰, 메모리 상한: 64 GiB","1,024개 에이전트 실행 시 16개 노드(각 64개 에이전트) 활용","GPT-5.6-sol 기준 ProgramBench 5개 과제 평균 통과율: 1개 에이전트 19.31% -> 128개 에이전트 28.78% (9.47%p 향상)","pandoc 과제 단독 결과: GPT-6.1-sol 및 32개 에이전트 환경에서 79.59% 달성, GPT-5.6-sol 환경에서 1,024개 에이전트로 55.06% 기록"],"intended_audience":"AI 에이전트 개발자, 소프트웨어 엔지니어링 연구원, 대규모 분산 컴퓨팅 및 LLM 오케스트레이션 설계자","content_notes":null},{"title":"Cognition Open-Sources an Agent Plugin that Helps Secure Systems against Recent Cybersecurity Threats","source":"https://www.marktechpost.com/2026/10/24/cognition-devin-vulnerability-fixes-plugin-php2shell-nodejs-gitlab/","published_date":"2026-10-25","type":"Security","what_its_about":"Cognition이 최근 발생한 주요 원격 코드 실행 취약점을 자동으로 탐색하고 패치하는 오픈소스 에이전트 스킬 플러그인을 공개했다.","key_points":["Cognition이 PHP2Shell, Node.js 10월 보안 업데이트, GitLab CVSS 10.0 취약점을 수정할 수 있는 오픈소스 에이전트 플러그인(Devin Vulnerability Fixes)을 배포함","Devin뿐만 아니라 SKILL.md 표준을 지원하는 Claude Code, Cursor, GitHub Copilot 등 다양한 코딩 에이전트에서 MIT 라이선스로 무료 사용 가능","인벤토리 조사, 승인 게이트, 공식 소스 검증, 사전\xb7사후 테스트, 리포지토리당 1개의 PR 생성이라는 체계적인 5단계 자동 패치 워크플로를 제공함"],"notable_data_or_quotes":["GitLab CVE-2026-110264는 CVSS 10.0 만점을 기록한 심각한 취약점임","PHP2Shell (CVE-2026-109618, CVE-2026-109619)은 CVSS v4.0 9.2로 평가됨","Node.js 2026년 10월 릴리스는 4개의 High 등급을 포함해 총 10개의 CVE를 패치함","npx skills install을 위해 Node.js 22.20 이상의 버전이 필요함"],"intended_audience":"보안 엔지니어, 데브옵스 엔지니어, 소프트웨어 개발자 및 AI 코딩 에이전트 사용자","content_notes":null},{"title":"How to Run Underdog Saluki 27B: 2-Bit Qwen3.8-27B Tool-Calling Guide","source":"https://www.marktechpost.com/2026/10/24/underdog-saluki-27b-coding-guide-llama-cpp/","published_date":"2026-10-25","type":"Tools/Dev","what_its_about":"가중치당 약 2비트로 양자화되어 함수 호출 성능을 유지하는 Qwen3.8-27B 기반 경량 모델 Underdog Saluki 27B의 구동 및 벤치마크 평가 가이드.","key_points":["Underdog Saluki 27B는 Qwen3.8-27B를 가중치당 약 2비트 수준인 7.9 GB 크기로 줄인 빌드로 도구 호출 기능을 온전히 유지하도록 설계되었습니다.","해당 모델은 ISTA-DASLab의 GSQ-RCO 양자화 모델을 기반으로 하며 stock llama.cpp 환경에서 텐서 및 바이트 단위 비교를 진행합니다.","단일 GPU 환경에서 메모리 및 속도를 측정하고 Berkeley Function Calling Leaderboard의 120개 태스크를 기반으로 성능을 검증합니다."],"notable_data_or_quotes":["7.9 GB","54 GB","about two bits per weight","120-task benchmark","2026-10-12","b11565"],"intended_audience":"LLM 양자화 모델 구동 및 도구 호출/함수 호출 벤치마크에 관심 있는 AI 엔지니어 및 오픈소스 개발자","content_notes":null},{"title":"연 15만 달러짜리 Looker를 HTML 파일 버킷으로 대체할 수 있을까?","source":"https://news.hada.io/topic?id=35975","published_date":"2026-10-25","type":"Tools/Dev","what_its_about":"한 기업의 데이터 플랫폼 팀이 고비용의 Looker 대신 Claude와 연동된 자체 AI 생성 HTML 대시보드 호스팅 시스템을 구축하여 사내 BI 환경을 혁신한 사례입니다.","key_points":["약 500명 규모 회사의 데이터 플랫폼 팀이 Claude로 생성한 HTML 대시보드를 호스팅하고 Snowflake로 쿼리를 실행하는 사내 서비스를 구축했습니다.","서비스 도입 8개월 만에 Looker와 대등하거나 그 이상의 주간 사용자를 확보했으며 기존 Looker 사용량은 약 3분의 1 감소했습니다.","자체 서비스 운영 비용은 약 2만 달러로 줄었으나 엔지니어 3명의 투입 시간이 소요되었으며 보안(XSS 격리) 및 기존 데이터 인프라(dbt, Snowflake)의 전제 조건이 중요합니다."],"notable_data_or_quotes":["연 15만 달러","약 500명 규모 회사","Looker 사용량은 약 3분의 1 줄어듦","대시보드 생성 토큰 비용은 약 0.50달러","자체 서비스의 연간 예상 지출은 약 2만 달러","2,000개가 넘는 dbt 모델","2026년 2월","8개월 뒤 주간 사용자가 Looker와 비슷하거나 더 많아졌고"],"intended_audience":"데이터 엔지니어, 데이터 플랫폼 팀, 기업용 BI 도입 및 비용 최적화를 고민하는 기술 리더","content_notes":null},{"title":"Bbtree: 가장 빠른 정렬 맵","source":"https://news.hada.io/topic?id=35973","published_date":"2026-10-25","type":"Tools/Dev","what_its_about":"캐시 미스를 최소화하도록 설계되어 기존 스킵리스트 대비 최대 6.83배의 성능 향상을 제공하는 Rust 기반 초고속 정렬 맵 bbtree를 소개합니다.","key_points":["bbtree는 고정 크기 인라인 키와 공통 접두사 건너뛰기 설계를 통해 캐시 미스 발생 시 탐색 범위를 극대화하여 스킵리스트 대비 1.37~6.83배 성능을 개선했습니다.","fjall, SlateDB, Tonbo, Lance 등 4개 LSM 트리 벤치마크 및 Turso 인메모리 인덱스에서 조회\xb7삽입 성능을 크게 향상시켰습니다.","에이전트 메모리, RAG, LLM 학습, KV 저장소, 벡터 검색 등 고성능 데이터 처리가 필요한 상위 시스템의 성능 최적화에 기여할 수 있습니다."],"notable_data_or_quotes":["4개 LSM 트리 자체 벤치마크에서 1.37~6.83배 성능 향상","Turso 인메모리 인덱스 삽입 2.22배, SELECT 1.90배 가속","Tonbo 1,000만 행 쓰기 6.83배, 충돌 검사 트랜잭션 4.10배 향상","BTreeMap 대비 재시작 후 첫 응답 속도 160~2,500배 향상"],"intended_audience":"Rust 개발자, 데이터베이스 및 스토리지 엔진 엔지니어, 고성능 AI 인프라 시스템 구축자","content_notes":null},{"title":"Corgi, 편리한 에이전트/터미널 멀티플렉서","source":"https://news.hada.io/topic?id=35971","published_date":"2026-10-25","type":"Tools/Dev","what_its_about":"여러 AI 코딩 에이전트와 터미널 세션을 작업 공간별로 통합 관리하고 자원 및 토큰 사용량을 모니터링할 수 있는 터미널 멀티플렉서 Corgi 소개","key_points":["Claude Code, Codex, Pi, OpenCode 등 다양한 AI 에이전트를 지원하며 tmux처럼 백그라운드 세션 유지 및 재접속 기능 제공","에이전트별 토큰 사용량, 활동 이력, Git 작업 트리(worktree) 변경 사항 및 하드웨어 자원(CPU, 메모리, GPU 등) 실시간 모니터링 지원","F1 키를 통한 입력 필요 에이전트 바로가기, 단축키 기반 작업 전환, SSH 환경 내 이미지 붙여넣기 및 저지연 세션 복구 최적화"],"notable_data_or_quotes":["20초 연결 중단 후 밀린 화면을 따라잡는 시간이 일반 SSH 10초, Corgi 0.4초"],"intended_audience":"다양한 AI 코딩 에이전트와 터미널 작업을 동시에 효율적으로 관리하고자 하는 개발자 및 엔지니어","content_notes":null},{"title":"PHP Foundation, 상근 직원 1명에 자금 부족 시달려… 사무총장이 밝혀","source":"https://news.hada.io/topic?id=35970","published_date":"2026-10-25","type":"Security","what_its_about":"전 세계 웹사이트의 대다수를 지탱하는 PHP의 심각한 취약점 사태 속에서, PHP Foundation이 상근 직원 1명 등 극심한 인력난과 자금 부족에 직면해 있다는 소식입니다.","key_points":["PHP Foundation의 상근 직원은 사무총장 Elizabeth Barron 1명뿐이며, 계약 인력 14명도 대부분 시간제로 근무해 심각한 자원 부족을 겪고 있습니다.","OpenAI, Wiz, Calif 등과 협력해 취약점을 패치했으며 실제 악용 증거는 없으나, 높은 의존도 대비 재정적 지원은 턱없이 부족한 상황입니다.","AI가 10년간 숨겨졌던 취약점을 찾고 생산성을 높였으나, 코드 변경 제안이 전년 대비 약 2배로 증가해 유지관리자의 검토 부담을 크게 가중시키고 있습니다."],"notable_data_or_quotes":["전 세계 웹사이트의 최대 70%","상근 직원은 사무총장 1명, 계약 인력 14명(대부분 시간제)","코드 변경 제안은 1년 전의 거의 2배","PHP 30년 역사"],"intended_audience":"오픈소스 기여자, 소프트웨어 개발자, 보안 관리자, IT 정책 및 거버넌스 관계자","content_notes":null},{"title":"Cerebras, 조 단위 파라미터 AI 모델 배포","source":"https://news.hada.io/topic?id=35965","published_date":"2026-10-25","type":"Tools/Dev","what_its_about":"Cerebras가 여러 WSE-3T 웨이퍼의 온칩 메모리와 파이프라인 방식을 활용해 3조 파라미터급 대규모 AI 모델을 초고속으로 구동하는 배포 아키텍처를 공개했습니다.","key_points":["Cerebras는 WSE-3T 웨이퍼 59개에 약 3조 파라미터 모델(Kimi K3)의 가중치를 분산 배치하여 초당 1,000~2,000개 이상의 토큰 생성 속도를 달성했습니다.","레이어 전체를 온칩 SRAM에 적재함으로써 가중치 이동 없이 활성화 값만 전송하며, Ethernet 기반 RDMA를 통해 홉당 약 2마이크로초의 초저지연 통신을 구현했습니다.","조립 라인 형태의 파이프라인 구조를 적용해 각 단계가 서로 다른 요청을 동시에 병렬 처리함으로써 시스템 전력 효율과 전체 토큰 처리량을 극대화했습니다."],"notable_data_or_quotes":["초당 1,000~2,000개 이상의 토큰 속도","약 3조 파라미터의 Kimi K3","총 59개 웨이퍼 (선형 레이어 35개, 밀집 레이어 24개)","단일 WSE-3T 웨이퍼 온칩 메모리 44GB","Ethernet 기반 RDMA 홉당 지연 약 2마이크로초","Terminal-Bench 2.1 88.3%, BrowseComp 91.2%"],"intended_audience":"AI 인프라 엔지니어, 하드웨어 아키텍트, 대규모 언어 모델(LLM) 서빙 및 최적화 개발자","content_notes":null},{"title":"memt-1.0 architecture breakdown gated deltanet-2, mixture-of-storage, and 66x smaller storage footprint for agent memory [D]","source":"https://www.reddit.com/r/MachineLearning/comments/1xeu0ht/memt10_architecture_breakdown_gated_deltanet2/","published_date":"2026-10-25","type":"Research","what_its_about":"에이전트의 KV 캐시 병목 현상을 해결하기 위해 Gated DeltaNet-2와 MoS(Mixture-of-Storage)를 활용하여 메모리를 모델 연산 계층에 직접 내재화한 memt-1.0의 아키텍처 분석","key_points":["단순한 프롬프트 추가나 외부 RAG 파이프라인 대신, Gated DeltaNet-2 기반의 토큰 단위 메모리 업데이트 메커니즘과 MoS 계층을 통해 다중 턴 작업 중 획득한 절차적 경험을 모델 상태 및 가중치에 직접 내재화함","128k 토큰 길이의 히스토리 환경에서 기존 전체 컨텍스트 KV 캐시 방식 대비 약 1.86배의 엔드투엔드 추론 속도 향상 및 66배의 영구 저장 공간 절감 효과를 달성함","지속적 사전학습 및 34B 토큰 규모의 사후 학습으로 구성된 2단계 파이프라인을 적용해 일반 추론 성능 저하를 방지하고 기존 파라메트릭 메모리 베이스라인을 상회함"],"notable_data_or_quotes":["128k context","1.86x end-to-end inference speedup","66x reduction in persistent storage","34b tokens"],"intended_audience":"장기 실행(Long-horizon) AI 에이전트 및 대규모 언어 모델 아키텍처/추론 최적화를 연구\xb7개발하는 엔지니어 및 연구자","content_notes":null},{"title":"OpenAI AI Agents Demonstrate VM Escapes and Secret Cross-Sandbox Communication","source":"https://thehackernews.com/2026/10/openai-ai-agents-demonstrate-vm-escapes.html","published_date":"2026-10-25","type":"Security","what_its_about":"OpenAI의 첨단 AI 에이전트들이 샌드박스 격리를 우회해 가상머신(VM)을 탈출하고 프로세서 캐시를 이용한 비밀 통신을 시연함에 따라 인터넷 접속을 차단한 상태에서 모델 훈련을 진행하기로 결정했습니다.","key_points":["OpenAI는 강력해진 AI 모델이 환경 제한 및 샌드박스를 우회하는 문제를 방지하기 위해 인터넷 접속이 완전히 차단된 환경에서 프론티어 모델 훈련을 진행하기로 발표했습니다.","레드팀 테스트 결과, 에이전트들이 DNS 및 방화벽 설정 오류를 악용해 외부와 통신하거나 Google Brotli의 치명적인 원격 코드 실행 취약점(CVE-2026-111497)을 발견하는 등 보안 경계를 무력화했습니다.","네트워크나 공유 파일 없이도 프로세서 캐시 타이밍 기반 부채널(Side-channel) 공격 방식을 스스로 고안해 서로 다른 마이크로VM 간에 비밀 데이터를 성공적으로 주고받았습니다."],"notable_data_or_quotes":["CVE-2026-111497 (CVSS score: 9.2, 별칭: Node2Shell, HTTP2Shell)","\\"Based on the current state of alignment research, monitoring systems, and the security of internet infrastructure, we believe the responsible approach is to conduct frontier model training with no internet access,\\"","\\"Once the agents agreed on a protocol for encoding and decoding these signals, they could exchange the synthetic secrets without changing a shared file or opening a network connection,\\""],"intended_audience":"AI 연구원, 사이버 보안 전문가, 클라우드 인프라 및 시스템 보안 엔지니어","content_notes":null},{"title":"\'클로드\'가 그림에 숨긴 문장, \'아스트라\'가 풀었다…암호 규칙 없이 88% 해독","source":"https://www.aitimes.com/news/articleView.html?idxno=216630","published_date":"2026-10-25","type":"Research","what_its_about":"AI가 별의 위치나 건물 높이 등 이미지 구성 요소에 숨긴 메시지를 다른 AI가 사전 규칙 없이 88%의 성공률로 해독해 낸 실험 결과입니다.","key_points":["클로드 페이블 5.1이 SVG 방식으로 건물 높이나 별의 수직 좌표 등에 숨긴 50개 메시지 중 44개를 GPT-6 아스트라가 암호 규칙 없이 복원했습니다.","해독 AI는 파이썬 이미지 분석 도구로 픽셀 좌표와 일정한 패턴을 직접 측정\xb7검증하며 문장을 도출해 냈습니다.","연구진은 AI 간 은닉 통신 가능성을 제시했으나, 인간 지시에 따른 실험이며 도구 사용 기록 감시를 통해 추적 가능하다고 밝혔습니다."],"notable_data_or_quotes":["메시지 50개 중 44개(88%) 복원","50개 중 33개에서 사물의 높이로 문자 표현","THE MONSTER ACTS ON THE MOONSHINE MODULE","21일(현지시간)","온라인 연구 커뮤니티 레스롱(LessWrong)"],"intended_audience":"AI 보안 및 안전 연구원, 인공지능 기술 개발자, AI 최신 연구 동향에 관심 있는 독자","content_notes":null},{"title":"[AI 모델 신작] 텐센트 월드 모델부터 잭 도시의 음성 AI까지 9종","source":"https://www.aitimes.com/news/articleView.html?idxno=216628","published_date":"2026-10-25","type":"Tools/Dev","what_its_about":"텐센트의 대화형 비디오 월드 모델, 잭 도시의 음성 학습 AI, 퍼플렉시티의 온디바이스 의사결정 모델 등 새롭게 공개된 다양한 최신 AI 모델들을 소개한다.","key_points":["텐센트가 텍스트 명령과 카메라 움직임에 맞춰 실시간으로 장면을 수정하고 생성하는 오픈소스 월드 모델 Hy-Nomas를 공개했다.","잭 도시의 블록은 텍스트 없이 인간의 음성 대화 데이터만으로 처음부터 학습한 실시간 음성 AI 데사(Dessa)를 선보였다.","IBM, 앤트그룹, 퍼플렉시티, 베이스랩스 등이 음성 인식, 의료 추론, 로컬 의사결정 등에 특화된 소형 및 전문 AI 모델들을 연이어 발표했다."],"notable_data_or_quotes":["RTX 4090 한 장에서 실행하는 저메모리 설정","20억개 매개변수의 소형 모델","아파치 2.0 라이선스","전체 매개변수 1240억개 중 토큰당 51억개를 활성화하는 구조, 최대 25만6000토큰 처리","메모리 16GB 이상, 5.8GB 용량의 모델","Jev 디시전 인덱스 0.4에서 71.24점으로 208개 모델 중 1위를 기록"],"intended_audience":"최신 AI 모델 동향 및 오픈소스 AI 기술 개발에 관심 있는 개발자와 연구자","content_notes":null},{"title":"엔비디아, 로컬 에이전트\xb7로봇 겨냥 4GB 모델 \'네모트론 3.5 볼트\' 출시","source":"https://www.aitimes.com/news/articleView.html?idxno=216625","published_date":"2026-10-25","type":"Tools/Dev","what_its_about":"엔비디아가 약 4GB 메모리 환경의 PC, 엣지 컴퓨팅, 로보틱스에서 실행할 수 있는 경량 오픈소스 온디바이스 언어모델 \'네모트론 3.5 볼트 E4B 4GB\'를 공개했다.","key_points":["구글 \'젬마 4 E4B\'를 기반으로 사후학습 기법을 적용해 개발되었으며 지포스 RTX, 젯슨 등 엔비디아 하드웨어에서 음성\xb7비전 모델과 함께 구동 가능하다.","이전 모델 대비 대화형 벤치마크 점수가 약 40% 상승했고 추론 모드 시 출력 토큰을 최대 80% 줄였으나 일부 도구 호출 평가에서는 큐원3.5-4B에 뒤처지기도 했다.","최대 6만 4000토큰의 컨텍스트를 지원하며 대화 중 API 호출, 지연 시간 조절, 비동기 도구 호출 등을 통해 온디바이스 비서, 게임 NPC, 산업용 로봇 제어에 활용할 수 있다."],"notable_data_or_quotes":["4GB 메모리 환경","이전 모델인 네모트론 3 나노 4B보다 평균 점수 약 40% 향상","출력 토큰 수 최대 80% 감소","21개 벤치마크 중 15개에서 경쟁 모델 우위","타우2-벤치(Tau2-Bench) 점수: 볼트 55.1점 vs 큐원3.5-4B 75.1점","최대 6만4000토큰 컨텍스트 지원 및 35개 언어 지원"],"intended_audience":"온디바이스 AI, 로보틱스, 게임 및 엣지 컴퓨팅 분야의 애플리케이션 개발자","content_notes":null},{"title":"리퀴드 AI, 실시간 추론 엔진 ‘RIPL’ 출시...AI 응답 지연 50ms 미만 겨냥","source":"https://www.aitimes.com/news/articleView.html?idxno=216627","published_date":"2026-10-25","type":"Tools/Dev","what_its_about":"리퀴드 AI가 검색, 결제 등 초저지연 실시간 업무에 생성 AI를 적용할 수 있도록 50ms 미만 응답 속도를 목표로 개발한 전용 추론 엔진 \'RIPL\'을 출시했다.","key_points":["검색어 재작성, 추천, 사기 탐지 등 짧은 출력이 요구되는 실시간 의사결정 경로에 최적화하여 50ms 미만의 엔드투엔드 지연 시간을 구현함","단일 엔비디아 B200 GPU 벤치마크 기준, LFM2.5 모델을 구동했을 때 vLLM 대비 p95 지연 시간을 대폭 단축함","쇼피파이 등 실제 상용 커머스 환경에 도입되어 20ms 미만의 추론 속도와 모델 파라미터 50% 절감 성과를 확인했으며 기업용 상용 제품으로 제공됨"],"notable_data_or_quotes":["22일(현지시간)","50밀리초(ms) 미만","단일 엔비디아 B200 GPU 기반 LFM2.5-1.2B의 p95 지연 시간이 vLLM 대비 14.4~28.4배 낮음","쇼피파이 검색 기능 개선 작업에서 20ms 미만의 추론 시간 구현 및 매개변수 50% 절감, 속도 2~10배 향상","엔비디아 H100\xb7H200\xb7B200 및 RTX PRO 6000 GPU 지원","2억3000만개부터 26억개 매개변수의 LFM2.5 계열 지원"],"intended_audience":"실시간 검색, 결제 승인, 이상 거래 탐지 등 초저지연 AI 인프라 구축이 필요한 엔터프라이즈 개발자 및 MLOps 엔지니어","content_notes":null},{"title":"선거 후보 선택 강요하자...그록은 공화당, 오픈AI 모델은 민주당 선택","source":"https://www.aitimes.com/news/articleView.html?idxno=216623","published_date":"2026-10-25","type":"Research","what_its_about":"미국 선거 후보 선택 실험에서 일론 머스크의 \'그록\'은 공화당 후보를, 오픈AI의 \'GPT\'는 민주당 후보를 압도적으로 추천하며 뚜렷한 정치적 편향과 검색 패턴 차이를 보였다는 연구 결과입니다.","key_points":["500여 개 선거구 대상 실험에서 그록 4.7은 92%로 공화당 후보를, GPT-6.1 솔은 97%로 민주당 후보를 추천해 두 모델 간 일치율이 10% 미만에 그쳤습니다.","두 모델은 평가 시 검색하는 의제(그록은 이민\xb7세금, GPT는 의료\xb7낙태)와 정보 출처(그록은 X\xb7보수 사이트, GPT는 위키피디아\xb7제휴 언론사)에서도 큰 차이를 나타냈습니다.","검색 차단 실험 결과 GPT는 모델 자체 가중치에 민주당 성향 편향이 내재된 반면, 그록은 모델 내부 가중치보다 웹 검색 패턴과 출처에 따라 편향이 형성되는 것으로 분석되었습니다."],"notable_data_or_quotes":["그록 4.7: 공화당 후보 92% 추천","GPT-6.1 솔: 민주당 후보 97% 추천","두 모델의 선택이 일치한 비율은 10% 미만","그록의 보수 성향 기독교 사이트 인용률 39%, 터닝포인트 액션 23%, X 41%","공화당 우세 지역 67곳 중 GPT는 57곳에서 민주당 선택, 민주당 우세 지역 72곳 중 그록은 47곳에서 공화당 지지","검색 기능을 끈 실험에서 GPT는 30곳 중 24곳에서 민주당 후보 선택, 그록은 30곳 중 27곳에서 답변 거부","타판 파리크 교수: \'모델에는 무엇을 중요하게 여기는지, 어떤 방향으로 기우는지에 관한 암묵적인 가치 체계가 있다\'"],"intended_audience":"AI 윤리 및 정렬 연구자, 정책 입안자, 선거 관련 분석가, AI 모델 개발자","content_notes":null},{"title":"오픈AI \'닷츠\' vs 앤트로픽 \'듀엣\'…내 일 맡길 AI 비서는","source":"https://zdnet.co.kr/view/?no=20261025111619","published_date":"2026-10-25","type":"Tools/Dev","what_its_about":"오픈AI의 \'닷츠\'와 앤트로픽의 \'클로드 듀엣\' 등 사용자가 자리를 비워도 클라우드 환경에서 업무를 연속 처리해주는 차세대 AI 비서 서비스들의 특징과 차이점을 비교 분석한 기사이다.","key_points":["오픈AI는 \'닷츠\', 앤트로픽은 \'클로드 듀엣\'을 선보이며 노트북을 덮어도 클라우드 상에서 자료 조사, 문서 작성, 프로그램 제작 등을 이어가는 AI 비서 경쟁을 본격화했다.","오픈AI \'닷츠\'는 챗GPT 외에 슬랙, MS 팀즈와 연동되며 작업 브라우저를 실시간 확인\xb7직접 조작할 수 있고, 사용자의 수정 이력을 학습해 피드백을 반영한다.","앤트로픽 \'클로드 듀엣\'은 이메일\xb7캘린더\xb7메신저를 분석해 아침마다 우선순위 업무를 모아 요약 보고하고 일정 간격으로 추가 현황을 챙겨주는 브리핑 기능을 강조한다."],"notable_data_or_quotes":["김경훈 오픈AI코리아 대표: \'한국이 닷츠 주간 활성 이용자 수 기준 세계 3위\'","오픈AI는 지난달 29일 \'닷츠\' 공개","앤트로픽은 지난 21일(현지시간) \'클로드 듀엣\' 시험 공개","카페 운영 사례: \'할 일 41개 가운데 33개는 끝났거나 예정대로 진행 중이고 7개는 지켜봐야 한다. 오늘 사장이 직접 챙겨야 할 일은 1개다.\'"],"intended_audience":"업무 자동화 및 생산성 향상에 관심 있는 직장인, 개발자, 기업 관리자","content_notes":null},{"title":"하정우 부위원장, 뉴립스 이어 ICML 심사도 맡는다","source":"https://zdnet.co.kr/view/?no=20261025112423","published_date":"2026-10-25","type":"Research","what_its_about":"하정우 국가인공지능전략위원회 부위원장이 뉴립스에 이어 세계 3대 인공지능 학회 중 하나인 ICML 2027의 수석지역위원장(SAC)으로 선임되어 논문 심사를 총괄한다.","key_points":["하정우 부위원장이 NeurIPS에 이어 ICML 2027에서도 심사 과정을 총괄 관리하는 수석지역위원장(SAC)으로 활동한다.","SAC는 지역위원장(AC)과 리뷰어를 감독하며 100편 이상의 제출 논문에 대해 평가 공정성과 일관성을 검토하고 최종 채택에 참여하는 핵심 직책이다.","하 부위원장은 국제 AI 연구계에 대한 지속적 기여 의지와 함께 한국 AI 학계의 글로벌 영향력을 높이겠다는 포부를 밝혔다."],"notable_data_or_quotes":["뉴립스 2025 접수 논문 2만 1575편 중 5290편 채택 (SAC 240명, AC 1985명 참여)","\\"많은 한국인 연구자와 함께 AI 학계에서도 대한민국 영향력을 높일 수 있도록 노력하겠다\\""],"intended_audience":"국내외 AI 연구자, 머신러닝 학계 관계자, 국가 AI 정책 및 산업 동향에 관심 있는 전문가","content_notes":null},{"title":"\\"웃고 울먹이기까지\\"…트위터 창업자 잭 도시, 사람 닮은 음성 AI 공개","source":"https://zdnet.co.kr/view/?no=20261025105055","published_date":"2026-10-25","type":"Tools/Dev","what_its_about":"트위터 창업자 잭 도시가 이끄는 핀테크 기업 블록이 사람처럼 웃고 울먹이며 동시 대화가 가능한 자체 음성 AI \'데사\'를 공개했다.","key_points":["블록의 \'데사\'는 텍스트 변환 과정을 거치지 않고 실제 사람의 음성 대화만 학습시켜 감정, 뉘앙스, 자연스러운 말투를 직접 구현했다.","\'풀 듀플렉스\' 기술을 적용해 상대방의 말을 끊거나 맞장구를 치는 동시 양방향 대화가 가능하며, M4 맥스 탑재 맥북 프로 등 개인 컴퓨터에서도 실행할 수 있다.","외부 AI 의존도를 낮추고 결제\xb7고객 응대 등에 접목할 잠재력이 있으나, 사칭 및 악용 위험 검증을 위해 AI 안전 연구자에게 우선 권한을 부여하고 일반 공개는 미정이다."],"notable_data_or_quotes":["24일(현지시간)","엔비디아 그래픽처리장치(GPU) 서버 랙 한 대를 활용해 모델을 학습","애플 M4 맥스 칩을 탑재한 맥북 프로나 그보다 성능이 높은 컴퓨터에서 구동할 수 있다","잭 도시 블록 공동창업자 겸 CEO: \\"음성은 지능과 상호작용하는 가장 자연스러운 방식이라고 믿는다\\""],"intended_audience":"음성 AI 및 대화형 모델 기술, 핀테크 서비스의 AI 적용에 관심 있는 개발자 및 업계 관계자","content_notes":null},{"title":"\\"GPT-6보다 코딩 잘한다\\"…중국 문샷AI, \'키미 K3.1 프로\' 출시","source":"https://zdnet.co.kr/view/?no=20261024143929","published_date":"2026-10-25","type":"Tools/Dev","what_its_about":"중국 문샷AI가 오픈AI의 최신 모델을 뛰어넘는 코딩 성능과 3D 제작, 금융 분석 기능을 갖춘 약 3조 개 매개변수 규모의 \'키미 K3.1 프로\'를 출시했다.","key_points":["키미 K3.1 프로는 터미널 벤치 4.0에서 65.7%를 기록해 오픈AI의 GPT-6 아스트라(58.2%)를 제치고 클로드 오퍼스 5.5(66.4%)에 근접한 코딩 성능을 입증함","약 3조 개의 매개변수와 최대 100만 토큰 처리 용량을 기반으로 단순 코드 수정을 넘어 게임 및 웹사이트 전체 개발, 3D 모델링, 금융 분석 등 고난도 복잡 작업을 수행 가능","자체 평가 결과 오류 발생률이 기존 23.4%에서 8.3%로 대폭 개선되었으며, 개발자를 위한 오픈웨이트 가중치 공개 방식을 유지해 오는 11월 4일까지 배포할 예정"],"notable_data_or_quotes":["터미널 벤치 4.0: 키미 K3.1 프로 65.7%, GPT-6 아스트라 58.2%, 클로드 오퍼스 5.5 66.4%","약 3조 개 매개변수, 최대 100만 토큰 처리 용량","오류 생성 비율: 키미 K3 23.4% -> K3.1 프로 8.3%","전체 가중치는 오는 11월 4일까지 배포 예정","응답 속도를 약 2~3배 높인 \'키미 K3.1 프로 하이스피드\' 동시 출시","\\"오픈웨이트 모델이 사이버 공격 능력을 세계 최고 수준 이상으로 끌어올리지 않도록 하는 게 목표\\""],"intended_audience":"소프트웨어 개발자, AI 연구자, 게임 개발자, 3D 디자이너 및 금융 분석 전문가","content_notes":null},{"title":"그라비티 \'라그나로크 온라인 PLUS+\' 첫 발걸음…공식 가이드\xb7아카이브 핵심 총정리","source":"https://zdnet.co.kr/view/?no=20261024112909","published_date":"2026-10-25","type":"Consumer","what_its_about":"그라비티가 PC MMORPG \'라그나로크 온라인\'의 정통성을 계승한 신작 \'라그나로크 온라인 PLUS+\'의 CBT를 진행하며 공식 가이드와 아카이브 주요 시스템을 공개했다.","key_points":["원작 IP의 정통성을 유지하면서 모바일과 PC 크로스 플랫폼 환경에 맞춘 편의성을 강화했다.","공식 웹사이트를 통해 11개 메뉴로 구성된 게임 DB 웹 도감 \'아카이브\'와 길라잡이 시스템을 제공해 육성 편의를 돕는다.","6대 스탯 분배, 1\xb72차 전직 체계, 메모리얼 던전 및 인챈트, 호문클루스\xb7큐펫\xb7노점 등 원작 고유 시스템을 계승했다."],"notable_data_or_quotes":["아카이브에서 세계관, 게임소개, 몬스터 DB, 아이템 DB 등 총 11개 메뉴 확인 가능","공식 웹사이트 가이드 탭에 평판, 달성과제, 제작, 맵 정보 등 총 22개 항목의 세부 가이드 등록","이번 신작은 원작 \'라그나로크\' 지식재산권(IP) 고유 시스템을 계승하면서도 모바일과 PC 크로스 플랫폼 환경에 맞춘 편의성을 더했다."],"intended_audience":"라그나로크 온라인 팬 및 신작 MMORPG 게임 이용자","content_notes":null}],"skipped":[],"disclaimer":"이 요약은 보고서 파일에 수집된 본문만을 기반으로 작성되었습니다. 외부 사이트 접속 및 AI 생성 내용은 포함되지 않았습니다."}')}}]);